// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // The reference oracle is not set, so atVersion should either revert or return a valid version.
        // The bug makes oracle() return address(0), which will cause atVersion to revert for any non-zero version due to isContract check in staticcall.
        // The general rule: if version == 0, atVersion returns; otherwise, the call reverts.
        if (version == 0) {
            // For version 0, atVersion may still revert if oracle is zero (no oracle set), but reference with no oracle would also revert.
            // To distinguish, we need to assume the reference oracle is not zero. Since we didn't set it, skip.
            vm.assume(false);
        } else {
            // For buggy version, atVersion will revert (because it calls staticcall on address(0)).
            vm.expectRevert();
            c.atVersion(version);
        }
        // The general rule: atVersion should not revert for version == 0 (oracle not set but valid?) - but reference also reverts if oracle not set.
        // Better rule: The oracle function must return a contract address.
        // We test this by asserting that oracle() returns a non-zero address.
        assertTrue(address(c.oracle()) != address(0), "Oracle should not be zero");
    }
}

