pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // Restrict to avoid out-of-bounds reverts that are not the bug
        vm.assume(oracleVersion <= type(uint128).max);

        // Call atVersion - should not revert in reference C
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSelector(c.atVersion.selector, oracleVersion)
        );

        // The rule: atVersion should never revert and the returned price must be zero
        // (because the oracle returns a zero address, so atVersion will try to call a non-contract)
        assertTrue(!success || abi.decode(data, (uint256, uint256, int256)).price == 0, "atVersion should not revert or price should be zero");
    }
}

