pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // We need a valid oracle version; the contract must have been initialized
        // We assume oracleVersion is within reasonable bounds
        vm.assume(oracleVersion > 0 && oracleVersion < 1000000);

        // Call atVersion and capture the return value
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSignature("atVersion(uint256)", oracleVersion)
        );

        // The call should not revert
        assertTrue(success);

        // Decode the result (OracleVersion struct: version, timestamp, price)
        (uint256 version, uint256 timestamp, int256 price) = abi.decode(data, (uint256, uint256, int256));

        // The reference ensures the price is the payoffDefinition's transform of the oracle's price.
        // Since the mutant returns a default payoffDefinition (zero fields), the transform will be zero,
        // but the actual oracle price should be nonzero (or at least different from zero in most cases).
        // However, the rule we assert is that price must be equal to the transform of the oracle's price 
        // using the stored payoffDefinition, which the mutant cannot satisfy because payoffDefinition is broken.
        // To make this testable without internal oracle, we assert a simpler invariant:
        // The price returned by atVersion should be zero only if the oracle version price is zero 
        // (since a default payoffDefinition transforms any price to zero).
        // But we cannot check oracle price. Instead, we assert that the price is never zero 
        // when the oracle has a nonzero version (to catch the mutant's zero-return).
        // This is a weaker rule but sufficient for the bug.
        // However, the user already tried similar rules. Let's try a different approach:
        // We assert that calling atVersion with the same version twice yields the same price.
        (bool success2, bytes memory data2) = address(c).call(
            abi.encodeWithSignature("atVersion(uint256)", oracleVersion)
        );
        assertTrue(success2);
        (uint256 version2, uint256 timestamp2, int256 price2) = abi.decode(data2, (uint256, uint256, int256));
        assertTrue(price == price2, "Price must be deterministic");

        // Also, the version returned should match the input version exactly
        assertTrue(version == oracleVersion, "Returned version must match input");
    }
}

